sys_variable_value.value:
(function execute(inputs, outputs) {
    
    const api = new x_neyu_google_nyu.LicenseAPI();
    const response = api.get(
        inputs.productId,
        inputs.skuId,
        inputs.userId
    );

    outputs.error = response.error;
    outputs.error_message = response.errorMessage;
    if (!response.error) {
        outputs.result = response.responseBody;
    }

})(inputs, outputs);

